package com.antlr4plus.parsing.security

import com.intellij.openapi.components.Service
import com.intellij.openapi.components.service
import com.intellij.openapi.project.Project
import java.io.InputStream
import java.nio.file.Path
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap

/** Session-only SHA-256 fingerprints for files generated by the plugin. */
@Service(Service.Level.PROJECT)
class GeneratedFileTrustStore {

    private val hashes = ConcurrentHashMap<String, String>()

    fun markGenerated(path: String, contentHash: String) {
        hashes[normalizePath(path)] = contentHash
    }

    fun get(path: String): String? = hashes[normalizePath(path)]

    /** Lexical lookup for UI hints. Security checks must use [get] and verify file content. */
    fun getCached(path: String): String? =
        normalizePathWithoutIo(path)?.let { normalized ->
            hashes[normalized]
        }

    fun remove(path: String): String? = hashes.remove(normalizePath(path))

    fun clear() {
        hashes.clear()
    }

    internal fun size(): Int = hashes.size

    private fun normalizePath(path: String): String =
        try {
            Path.of(path).toRealPath().toString()
        } catch (_: Exception) {
            normalizePathWithoutIo(path) ?: path
        }

    private fun normalizePathWithoutIo(path: String): String? = runCatching {
        Path.of(path).toAbsolutePath().normalize().toString()
    }
        .getOrNull()

    companion object {
        fun getInstance(project: Project): GeneratedFileTrustStore = project.service()

        fun computeHash(content: ByteArray): String = digest().apply { update(content) }.hexDigest()

        fun computeHash(content: InputStream): String {
            val digest = digest()
            val buffer = ByteArray(DEFAULT_BUFFER_SIZE)
            while (true) {
                val count = content.read(buffer)
                if (count < 0) break
                if (count > 0) digest.update(buffer, 0, count)
            }
            return digest.hexDigest()
        }

        private fun digest(): MessageDigest = MessageDigest.getInstance("SHA-256")

        private fun MessageDigest.hexDigest(): String = digest().joinToString("") { "%02x".format(it) }
    }
}
